import heapq

def shortest(N: int, edgeList: list) -> int:
    adj = [[] for _ in range(N)]
    for u, v, w in edgeList:
        adj[u].append((v, w))

    dist = {0: 0}
    heap = [(0, 0)]

    while heap:
        d, u = heapq.heappop(heap)
        if d > dist.get(u, float('inf')):
            continue
        if u == N - 1:
            return d
        for v, w in adj[u]:
            new_dist = d + w
            if new_dist < dist.get(v, float('inf')):
                dist[v] = new_dist
                heapq.heappush(heap, (new_dist, v))

    return -1
